mapper.update:
UPDATE CLAIMS
SET
detail_file_path = #{detail_file_path, jdbcType=VARCHAR},
receipt_file_path = #{receipt_file_path, jdbcType=VARCHAR},
etc_file_path = #{etc_file_path, jdbcType=VARCHAR}
WHERE claim_id = #{claim_id, jdbcType=NUMERIC}

mapper.select:
SELECT c.claim_id, c.claim_date, c.accident_type, c.claim_status, p1.person_name AS insured_name, c.beneficiary_name FROM CLAIMS c JOIN INSURANCE_CONTRACTS ic ON c.contract_id = ic.contract_id JOIN CUSTOMERS cu ON ic.customer_id = cu.customer_id JOIN PERSONS p1 ON cu.person_id = p1.person_id WHERE cu.customer_id = #{customerId}
AND c.claim_date >= #{start}
AND c.claim_date <= #{end}
ORDER BY c.claim_date DESC
